import React,{useState} from 'react';import{createRoot}from'react-dom/client';import{OnboardingProvider,useOnboarding}from'../../src/onboarding/OnboardingProvider';
const store:Record<string,any>={};const fakeApi=async(path:string,options?:any)=>{if(!options)return {...store};const id=path.split('/').pop()!;store[id]={...JSON.parse(options.body),completed_at:new Date().toISOString()};return store[id]};
function Controls(){const tour=useOnboarding();return <><button onClick={()=>tour.start('T1')}>Повторить</button>{tour.launcher}</>}
function Demo(){const mode=new URLSearchParams(location.search).get('mode');const[route,setRoute]=useState(mode==='questionnaire'?'/contracts':mode==='template'?'/templates':'/');return <OnboardingProvider user={{id:'test',roles:mode==='manager'||mode==='template'?['dpo_specialist']:[]}} api={fakeApi} route={route} navigate={setRoute}><aside data-tour="sidebar"><button data-tour="sidebar-create">Создать</button><nav data-tour="sidebar-nav">Меню</nav><button data-tour="profile">Профиль</button></aside><main><div data-tour="home-metrics" style={{marginTop:500}}>Метрики</div><div data-tour="home-new-document">Новый</div><div data-tour="home-recents">Недавние</div><div data-tour="catalog-search">Поиск</div><div data-tour="catalog-cards">Каталог</div><div data-tour="catalog-card">Договор</div><div data-tour="documents-row">Документ</div><div data-tour="documents-actions">Действия</div>{mode==='questionnaire'&&<div data-tour="q-header">Анкета</div>}{mode==='template'&&<div data-tour="tpl-tabs">Редактор</div>}{mode==='template'&&<div data-tour="tpl-title">Шаблон</div>}{mode==='template'&&<div data-tour="tpl-upload">Загрузить</div>}<Controls/></main></OnboardingProvider>};createRoot(document.getElementById('root')!).render(<Demo/>);
